import {WorldGame,roadWidth,areaName,END_Z,clamp} from './world-engine.js';
import {WorldView} from './world-renderer.js';
import {readWords} from './vocab.js';
const SAMPLE=`reduce,減らす\naffect,影響を与える\npublish,出版する\ncompete,競う\nexplore,探索する\nrecognize,認識する\nemphasize,強調する\naccompany,同行する\ncrowded,混雑した\nvaluable,貴重な\naccurate,正確な\ngrant,補助金\ndestination,目的地\ncapacity,能力\nproof,証拠\nanniversary,記念日\nfound,設立する\ninclude,含む`;
const $=id=>document.getElementById(id),KEY='vocab-castle-words-v1';let game=null,view=null,paused=false,last=0,toastTime=0,previousGate=null,nav=null,muted=true,audio=null,endPending=false;const pointers=new Map(),keys=new Set();
function tone(freq,duration=.1){if(muted)return;try{audio??=new(window.AudioContext||window.webkitAudioContext)();audio.resume();const o=audio.createOscillator(),g=audio.createGain();o.type='triangle';o.frequency.setValueAtTime(freq,audio.currentTime);o.frequency.exponentialRampToValueAtTime(freq*.55,audio.currentTime+duration);g.gain.setValueAtTime(.055,audio.currentTime);g.gain.exponentialRampToValueAtTime(.001,audio.currentTime+duration);o.connect(g);g.connect(audio.destination);o.start();o.stop(audio.currentTime+duration);}catch{}}
function toast(text,bad=false){$('toast').textContent=text;$('toast').classList.toggle('bad',bad);$('toast').classList.add('show');toastTime=performance.now()+2500;}
function event(type,data){
 if(type==='correct'){toast(`正解！ ${data.word}\n火力 ×${data.power} · ${data.tier}`);tone(900,.25);}
 if(type==='wrong'){toast(`正解は ${data.word} = ${data.meaning}\n火力半減・射撃停止`,true);tone(120,.3);}
 if(type==='clear'){toast('敵を撃破！ 次の道が開いた');tone(600,.15);}
 if(type==='damage')tone(95,.12);
 if(type==='barrel'){toast('連鎖爆発！');tone(70,.24);}
 if(type==='shock'){toast('衝撃波！');tone(240,.3);}
 if(type==='pickup'){toast(data.type==='heal'?'補給箱：耐久 ＋28':'補給箱：火力 ＋2');tone(800,.17);}
 if(type==='boss')toast('魔王の庭\n赤い突進予告から離れよう');
 if(type==='bossStunned')toast('壁に激突！ 弱点露出！');
 if(type==='bossDown')toast('魔王を撃破！ 奥の金色の出口へ');
 if(type==='end')endPending=data;
}
function clearInput(){pointers.clear();keys.clear();nav=null;game?.setMove(0,0);for(const id of['moveStick','aimStick'])$(id).querySelector('i').style.transform='';}
function start(raw){const p=readWords(raw);if(p.errors.length){$('formError').textContent=p.errors[0];return false;}view?.dispose();view=null;game=new WorldGame(p.entries,{event});try{view=new WorldView($('gameCanvas'),game);}catch(e){game=null;$('formError').textContent='3D表示を開始できませんでした。WebGLが利用できるSafari／Chromeで開いてください。';return false;}try{localStorage.setItem(KEY,raw);}catch{}clearInput();paused=false;endPending=false;previousGate=null;$('formError').textContent='';for(const id of['setupOverlay','endOverlay','pauseOverlay'])$(id).classList.add('hidden');toast('左スティックで前進\n敵は自動で狙う。右で手動照準');last=performance.now();return true;}
function setup(){paused=true;clearInput();$('setupOverlay').classList.remove('hidden');$('pauseOverlay').classList.add('hidden');$('endOverlay').classList.add('hidden');}
function pause(value){if(!game||game.mode!=='play')return;paused=value;clearInput();$('pauseOverlay').classList.toggle('hidden',!value);}
function showEnd(data){clearInput();$('endKicker').textContent=data.win?'VICTORY':'DEFEAT';$('endTitle').textContent=data.win?'城を突破した！':'戦車が動けなくなった';$('endReason').textContent=data.reason;$('endScore').textContent=game.score.toLocaleString()+' PTS';$('endStats').textContent=`単語 ${game.correct} / ${game.answered} 問正解 · 撃破 ${game.kills} 体`;$('combatStats').textContent=`${Math.round(game.time)}秒 · 爆発 ${game.stats.barrels} 回 · 衝撃波 ${game.stats.shockwaves} 回`;$('missedList').replaceChildren();for(const w of game.missed.values()){const span=document.createElement('span');span.textContent=w.word+' — '+w.meaning;$('missedList').append(span);}$('missedWrap').classList.toggle('hidden',!game.missed.size);$('endOverlay').classList.remove('hidden');}
function choose(side){if(!game?.activeGate||paused)return;const gate=game.activeGate;nav={x:(side===0?-1:1)*(roadWidth(gate.z)*.48),z:gate.z+65};game.autoAim();}
function hud(){if(!game)return;const p=game.player,g=game.activeGate;$('areaLabel').textContent=areaName(p.z);$('ammoLabel').textContent=game.jam>0?'射撃停止':`火力 ×${game.power}`;$('scoreLabel').textContent=game.score.toLocaleString()+' PTS';$('healthLabel').textContent=Math.round(game.hp);$('healthFill').style.width=game.hp+'%';$('healthFill').style.background=game.hp<30?'#ff6f87':'';$('weaponLabel').textContent=game.tier;$('travelFill').style.width=clamp(p.z/END_Z*100,0,100)+'%';$('autoButton').textContent=game.manualAim?'手動照準 → 自動へ':'自動照準 ON';$('burstButton').disabled=game.charge<100||game.mode!=='play';$('burstButton').classList.toggle('ready',game.charge>=100);$('burstCount').textContent=game.charge>=100?'発動':`${game.charge}%`;
 const lock=game.currentLock();$('mission').textContent=game.bossDead?'魔王撃破！ 奥の金色の出口へ':game.boss?'赤い突進を避け、壁に激突したら攻撃':g?'意味に合う門を通ろう · 敵がスローモーションに':lock?`敵を倒して道を開ける · あと ${game.enemies.filter(e=>e.wave===lock.id).length} 体`:'左スティックで前進 · 壁や柱を使って戦おう';
 const active=!!g&&game.mode==='play';$('questionPanel').classList.toggle('hidden',!active);for(const id of['gateLeft','gateRight'])$(id).classList.toggle('hidden',!active);
 if(active){if(previousGate!==g){$('questionNumber').textContent=`単語ゲート ${g.id+1} / 6`;$('questionText').textContent=`「${g.target.meaning}」`;$('rewardText').textContent=game.power>=24?'正解：火力維持＋耐久回復 ／ 不正解：火力半減':`正解：火力 ${g.operation.join('')} ／ 不正解：半減＋射撃停止`;['gateLeft','gateRight'].forEach((id,i)=>{$(id).querySelector('strong').textContent=g.words[i].word;$(id).setAttribute('aria-label',`${i===0?'左':'右'}の門 ${g.words[i].word}`);});previousGate=g;}
 $('gateTime').textContent=Math.max(0,g.duration-g.age).toFixed(1)+'秒';$('timerFill').style.transform=`scaleX(${Math.max(0,1-g.age/g.duration)})`;
 ['gateLeft','gateRight'].forEach((id,i)=>{const q=view.project((i===0?-1:1)*roadWidth(g.z)*.5,g.z,125);$(id).style.left=clamp(q.x*100,22,78)+'%';$(id).style.top=clamp(q.y*100,43,73)+'%';$(id).classList.toggle('chosen',nav&&Math.sign(nav.x)===(i===0?-1:1));});}
 const boss=game.boss;$('bossHealth').classList.toggle('hidden',!boss||game.bossDead);if(boss){$('bossHealthBar').style.width=Math.max(0,boss.hp/boss.maxHp*100)+'%';$('bossState').textContent=boss.phase==='stunned'?'弱点露出！ 攻撃のチャンス':boss.phase==='windup'?'突進予告！ 赤い線から離れろ':'魔王ゴーレム';}
}
function step(t){const dt=last?Math.min(.04,(t-last)/1000):0;last=t;if(game&&view){if(!paused&&!document.hidden&&game.mode==='play'){
 if(keys.size){const x=(keys.has('d')||keys.has('ArrowRight')?1:0)-(keys.has('a')||keys.has('ArrowLeft')?1:0),z=(keys.has('w')||keys.has('ArrowUp')?1:0)-(keys.has('s')||keys.has('ArrowDown')?1:0);game.setMove(x,z);}
 else if(nav){const maxX=roadWidth(game.player.z)-game.player.r-25;const targetX=clamp(nav.x,-maxX,maxX),dx=targetX-game.player.x,dz=nav.z-game.player.z;if(Math.hypot(nav.x-game.player.x,dz)<22){nav=null;game.setMove(0,0);}else{const length=Math.hypot(dx,dz)||1;game.setMove(dx/length,dz/length);}}
 game.update(dt);}view.render();hud();if(endPending){const data=endPending;endPending=false;showEnd(data);}}
 if(performance.now()>toastTime)$('toast').classList.remove('show');requestAnimationFrame(step);}
function stick(id,kind){const el=$(id);const update=ev=>{const b=el.getBoundingClientRect(),radius=b.width*.36;let dx=(ev.clientX-(b.left+b.width/2))/radius,dy=(ev.clientY-(b.top+b.height/2))/radius;const l=Math.max(1,Math.hypot(dx,dy));dx/=l;dy/=l;el.querySelector('i').style.transform=`translate(${dx*radius}px,${dy*radius}px)`;if(kind==='move'){nav=null;game.setMove(dx,-dy);}else if(Math.hypot(dx,dy)>.12)game.aimDirection(dx,-dy);};el.addEventListener('pointerdown',ev=>{if(!game||paused||game.mode!=='play')return;ev.preventDefault();el.setPointerCapture(ev.pointerId);pointers.set(ev.pointerId,kind);update(ev);});el.addEventListener('pointermove',ev=>{if(pointers.get(ev.pointerId)===kind&&!paused)update(ev);});const stop=ev=>{if(pointers.get(ev.pointerId)!==kind)return;pointers.delete(ev.pointerId);el.querySelector('i').style.transform='';if(kind==='move')game?.setMove(0,0);};el.addEventListener('pointerup',stop);el.addEventListener('pointercancel',stop);}
stick('moveStick','move');stick('aimStick','aim');
$('gameCanvas').addEventListener('pointerdown',ev=>{if(!game||paused||game.mode!=='play')return;const b=ev.currentTarget.getBoundingClientRect(),point=view.groundAt((ev.clientX-b.left)/b.width,(ev.clientY-b.top)/b.height);if(point)game.aimAt(point.x,point.z);});
$('startButton').onclick=()=>start($('wordsInput').value);$('sampleButton').onclick=()=>{$('wordsInput').value=SAMPLE;start(SAMPLE);};$('replayButton').onclick=()=>start($('wordsInput').value);$('changeButton').onclick=setup;$('editButton').onclick=setup;$('pauseButton').onclick=()=>pause(true);$('resumeButton').onclick=()=>pause(false);$('gateLeft').onclick=()=>choose(0);$('gateRight').onclick=()=>choose(1);$('autoButton').onclick=()=>game?.autoAim();$('burstButton').onclick=()=>{if(!paused)game?.shockwave();};$('soundButton').onclick=()=>{muted=!muted;$('soundButton').textContent=muted?'音 OFF':'音 ON';tone(700);};
window.addEventListener('keydown',ev=>{if(!game||game.mode!=='play'||!$('setupOverlay').classList.contains('hidden'))return;if(ev.key==='Escape'){pause(!paused);return;}if(paused)return;const key=ev.key.length===1?ev.key.toLowerCase():ev.key;if(['w','a','s','d','ArrowUp','ArrowDown','ArrowLeft','ArrowRight'].includes(key)){ev.preventDefault();nav=null;keys.add(key);}if(key==='q'){ev.preventDefault();game.shockwave();}if(key==='e')game.autoAim();});window.addEventListener('keyup',ev=>{keys.delete(ev.key.length===1?ev.key.toLowerCase():ev.key);if(!keys.size&&!pointers.size)game?.setMove(0,0);});window.addEventListener('blur',()=>pause(true));document.addEventListener('visibilitychange',()=>{if(document.hidden)pause(true);});window.addEventListener('resize',()=>view?.resize());
try{$('wordsInput').value=localStorage.getItem(KEY)||'';}catch{}
if(document.modelContext?.registerTool){for(const tool of[{name:'start_vocabulary_game',description:'単語と訳の行リストから3D戦車ゲームを開始する。',inputSchema:{type:'object',properties:{wordList:{type:'string'}},required:['wordList'],additionalProperties:false},annotations:{readOnlyHint:false},execute(input){if(typeof input?.wordList!=='string')throw Error('wordList が必要です');$('wordsInput').value=input.wordList;if(!start(input.wordList))throw Error($('formError').textContent);return{started:true,words:game.pack.length};}},{name:'move_to_vocabulary_gate',description:'左右の単語ゲートへ戦車を進める。通過時に解答が確定する。',inputSchema:{type:'object',properties:{side:{type:'string',enum:['left','right']}},required:['side'],additionalProperties:false},annotations:{readOnlyHint:false},execute(input){if(!['left','right'].includes(input?.side)||!game?.activeGate||paused)throw Error('門へ移動できません');choose(input.side==='left'?0:1);return{movingTo:input.side};}}]){try{Promise.resolve(document.modelContext.registerTool(tool)).catch(()=>{});}catch{}}}
requestAnimationFrame(step);
